/* =============================================================================
 * explore.js — immersive "Explore" edition
 * ECharts visualisations fed by docs/article-data/*.json (generated by
 * scripts_notebooks/export_article_data.R). Vanilla JS, no other dependency.
 * ========================================================================== */
(function () {
  "use strict";
  if (typeof echarts === "undefined") return;

  var THEMES = {
    light: {
      cyan: "#2e9db7", blue: "#4361ee", peri: "#7b8fe0", lime: "#4f7a44",
      orange: "#d98a35", pink: "#c94f86", ink: "#101828", muted: "#3b4358",
      soft: "#6b7694", grid: "rgba(27,33,48,.12)",
      palette: ["#2e9db7", "#4361ee", "#7b8fe0", "#6b9e5f", "#d98a35", "#c94f86", "#3f9c86", "#8b6fd6"]
    },
    dark: {
      cyan: "#5fd0e6", blue: "#7e9bff", peri: "#b7c3ff", lime: "#c3ecb6",
      orange: "#f5b877", pink: "#ea86b1", ink: "#f3f6ff", muted: "#c9d1e4",
      soft: "#9aa6c2", grid: "rgba(255,255,255,.16)",
      palette: ["#5fd0e6", "#7e9bff", "#b7c3ff", "#c3ecb6", "#f5b877", "#ea86b1", "#9fe0cf", "#d3bcff"]
    }
  };
  var mode = "light";
  var C = {};
  var PALETTE = [];
  function applyMode(m, persist) {
    mode = (m === "dark") ? "dark" : "light";
    var t = THEMES[mode];
    Object.keys(t).forEach(function (k) { C[k] = t[k]; });
    PALETTE.length = 0;
    t.palette.forEach(function (p) { PALETTE.push(p); });
    if (document.body) document.body.classList.toggle("explore-dark", mode === "dark");
    if (persist) { try { localStorage.setItem("m2h-explore-theme", mode); } catch (e) { /* ignore */ } }
    var btn = document.getElementById("xThemeToggle");
    if (btn) btn.textContent = mode === "dark" ? "Light theme" : "Dark theme";
  }

  function base() {
    return {
      backgroundColor: "transparent",
      textStyle: { fontFamily: "Arial, Helvetica, sans-serif", color: C.muted },
      color: PALETTE,
      tooltip: {
        backgroundColor: mode === "dark" ? "#0c1220" : "#ffffff",
        borderColor: mode === "dark" ? "rgba(255,255,255,.22)" : "rgba(27,33,48,.18)",
        borderWidth: 1, textStyle: { color: C.ink, fontSize: 12 },
        extraCssText: mode === "dark" ? "box-shadow:0 8px 24px rgba(0,0,0,.45)" : "box-shadow:0 8px 24px rgba(27,33,48,.16)"
      },
      legend: { textStyle: { color: C.muted }, inactiveColor: C.soft, top: 40, type: "scroll", itemGap: 12 },
      grid: { left: 12, right: 18, top: 74, bottom: 44, containLabel: true }
    };
  }
  function axis(name) {
    return {
      name: name, nameLocation: "middle", nameGap: 30,
      nameTextStyle: { color: C.soft },
      axisLine: { lineStyle: { color: C.grid } },
      axisTick: { lineStyle: { color: C.grid } },
      axisLabel: { color: C.soft },
      splitLine: { lineStyle: { color: C.grid } }
    };
  }
  var instances = [];
  function render(el, option) {
    if (el._chart && !el._chart.isDisposed()) el._chart.dispose();
    var inst = echarts.init(el, null, { renderer: "canvas" });
    inst.setOption(option);
    instances.push(inst);
    el._chart = inst;
    return inst;
  }
  function refit(inst, fn) {
    if (!inst || (inst.isDisposed && inst.isDisposed())) return;
    fn();
    inst.resize();
  }

  var resizeTimer = null;
  window.addEventListener("resize", function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function () {
      instances.forEach(function (i) { if (!i.isDisposed()) i.resize(); });
    }, 160);
  });

  /* reading progress */
  var progress = document.getElementById("readProgress");
  function updateProgress() {
    if (!progress) return;
    var doc = document.documentElement;
    var max = doc.scrollHeight - doc.clientHeight;
    progress.style.width = (max > 0 ? (doc.scrollTop / max) * 100 : 0) + "%";
  }
  window.addEventListener("scroll", updateProgress, { passive: true });
  window.addEventListener("resize", updateProgress);
  updateProgress();

  function uniq(arr) { return Array.from(new Set(arr)); }
  function finite(v) { return typeof v === "number" && isFinite(v); }
  function nfmt(v, d) { return (v == null || isNaN(v)) ? "–" : Number(v).toFixed(d == null ? 2 : d); }
  function title(text, sub) {
    return { text: text, subtext: sub || "", left: 0, top: 0, textStyle: { color: C.ink, fontSize: 12, fontWeight: 700 }, subtextStyle: { color: C.soft, fontSize: 10 } };
  }
  function slope(x, y) {
    var n = 0, sx = 0, sy = 0, sxy = 0, sxx = 0;
    for (var i = 0; i < x.length; i++) {
      if (!finite(x[i]) || !finite(y[i])) continue;
      n++; sx += x[i]; sy += y[i]; sxy += x[i] * y[i]; sxx += x[i] * x[i];
    }
    if (n < 3) return null;
    var s = (n * sxy - sx * sy) / (n * sxx - sx * sx);
    return { m: s, b: (sy - s * sx) / n, n: n };
  }

  /* ── renderers ──────────────────────────────────────────────────────────── */
  var R = {};

  R.genusBar = function (el, d) {
    d = d.slice().sort(function (a, b) { return a.datasets - b.datasets; });
    el.style.height = Math.max(260, d.length * 26) + "px";
    render(el, Object.assign(base(), {
      title: title("Immunization datasets by genus"),
      grid: { left: 12, right: 40, top: 34, bottom: 40, containLabel: true },
      xAxis: Object.assign(axis("datasets"), { type: "value" }),
      yAxis: Object.assign(axis(""), { type: "category", data: d.map(function (r) { return r.genus; }) }),
      series: [{
        type: "bar", data: d.map(function (r) {
          var hot = (r.genus === "Homo" || r.genus === "Mus");
          return { value: r.datasets, itemStyle: { color: hot ? C.cyan : C.peri, borderRadius: [0, 4, 4, 0] } };
        }),
        label: { show: true, position: "right", color: C.muted, fontSize: 10 },
        barWidth: "62%"
      }]
    }));
  };

  R.sankey = function (el, d) {
    var links = d.filter(function (r) { return Number(r.value) > 0; });
    var nodes = uniq(links.reduce(function (a, r) { return a.concat([r.source, r.target]); }, []))
      .map(function (n) { return { name: n }; });
    el.style.height = "420px";
    render(el, Object.assign(base(), {
      title: title("How the datasets narrow down", "pathogen type → target pathogen"),
      tooltip: Object.assign({}, base().tooltip, { trigger: "item" }),
      series: [{
        type: "sankey", data: nodes, links: links.map(function (r) { return { source: r.source, target: r.target, value: Number(r.value) }; }),
        emphasis: { focus: "adjacency" },
        lineStyle: { color: "gradient", opacity: .35, curveness: .5 },
        label: { color: C.muted, fontSize: 11 },
        itemStyle: { borderWidth: 0 },
        levels: [
          { depth: 0, itemStyle: { color: C.cyan }, lineStyle: { color: "source", opacity: .4 } },
          { depth: 1, itemStyle: { color: C.blue }, lineStyle: { color: "source", opacity: .4 } }
        ]
      }]
    }));
  };

  R.studiesTable = function (el, d) {
    var cols = [
      ["gse", "GSE"], ["pathogen", "Pathogen"], ["vaccine", "Vaccine type"],
      ["adjuvant", "Adjuvant"], ["route", "Route"], ["sample", "Sample"],
      ["sequencing", "Platform"]
    ];
    var PAGE = 20;
    var state = { q: "", sort: "gse", dir: 1, page: 0 };
    el.innerHTML =
      '<div class="x-controls">' +
      '<input class="x-search" type="search" placeholder="Filter by pathogen, vaccine, GSE…" aria-label="Filter studies">' +
      '<span class="x-pageinfo"></span>' +
      '<button class="x-chip x-prev" type="button" aria-label="Previous page">‹ Prev</button>' +
      '<button class="x-chip x-next" type="button" aria-label="Next page">Next ›</button>' +
      "</div>" +
      '<div class="x-table-wrap"><table class="x-table"><thead><tr>' +
      cols.map(function (c) { return '<th data-k="' + c[0] + '">' + c[1] + "</th>"; }).join("") +
      "</tr></thead><tbody></tbody></table></div>" +
      '<p class="x-table-note"></p>';
    var tbody = el.querySelector("tbody"), note = el.querySelector(".x-table-note"),
        thead = el.querySelector("thead"), pageInfo = el.querySelector(".x-pageinfo"),
        prev = el.querySelector(".x-prev"), next = el.querySelector(".x-next");
    function pageSlice() {
      var q = state.q.toLowerCase();
      var rows = d.filter(function (r) {
        if (!q) return true;
        return cols.some(function (c) { return String(r[c[0]] || "").toLowerCase().indexOf(q) >= 0; });
      });
      rows.sort(function (a, b) {
        var va = a[state.sort], vb = b[state.sort];
        return String(va == null ? "" : va).localeCompare(String(vb == null ? "" : vb)) * state.dir;
      });
      var pages = Math.max(1, Math.ceil(rows.length / PAGE));
      if (state.page >= pages) state.page = pages - 1;
      if (state.page < 0) state.page = 0;
      return { rows: rows, pages: pages, slice: rows.slice(state.page * PAGE, state.page * PAGE + PAGE) };
    }
    function draw() {
      var p = pageSlice();
      tbody.innerHTML = p.slice.map(function (r) {
        return "<tr>" + cols.map(function (c) {
          var v = r[c[0]]; v = (v == null || v === "" || v === "NA") ? "–" : v;
          return "<td>" + String(v) + "</td>";
        }).join("") + "</tr>";
      }).join("");
      var from = p.rows.length ? state.page * PAGE + 1 : 0;
      note.textContent = "Showing " + from + "–" + (state.page * PAGE + p.slice.length) +
        " of " + p.rows.length + " studies" + (state.q ? " (filtered from " + d.length + ")" : "");
      pageInfo.textContent = "Page " + (state.page + 1) + " / " + p.pages;
      prev.disabled = state.page === 0;
      next.disabled = state.page >= p.pages - 1;
    }
    el.querySelector(".x-search").addEventListener("input", function (e) { state.q = e.target.value; state.page = 0; draw(); });
    prev.addEventListener("click", function () { state.page = Math.max(0, state.page - 1); draw(); });
    next.addEventListener("click", function () { state.page += 1; draw(); });
    thead.addEventListener("click", function (e) {
      var k = e.target.getAttribute("data-k"); if (!k) return;
      if (state.sort === k) state.dir *= -1; else { state.sort = k; state.dir = 1; }
      state.page = 0;
      draw();
    });
    draw();
    el.classList.add("x-table-ready");
  };

  R.dgeBar = function (el, d) {
    var key = function (r) { return r.pathogen + " · " + r.timepoint; };
    var conditions = uniq(d.map(key));
    var organisms = uniq(d.map(function (r) { return r.organism; }));
    el.style.height = Math.max(300, conditions.length * 26) + "px";
    var series = organisms.map(function (o, i) {
      return {
        name: o, type: "bar", barMaxWidth: 16,
        itemStyle: { color: PALETTE[i % PALETTE.length], borderRadius: [0, 4, 4, 0] },
        data: conditions.map(function (c) {
          return d.filter(function (r) { return key(r) === c && r.organism === o; })
            .reduce(function (a, r) { return a + (r.n_sig || 0); }, 0);
        })
      };
    });
    render(el, Object.assign(base(), {
      title: title("Significant genes by condition", "adj. p < 0.05 · per species and time point"),
      legend: { textStyle: { color: C.muted }, top: 34, itemGap: 12 },
      grid: { left: 12, right: 48, top: 66, bottom: 40, containLabel: true },
      xAxis: Object.assign(axis("DEGs"), { type: "value" }),
      yAxis: Object.assign(axis(""), {
        type: "category", data: conditions,
        axisLabel: { color: C.soft, fontSize: 10, interval: 0 }
      }),
      series: series
    }));
  };

  R.dgeFacets = function (el, d) {
    var orderKey = function (t) {
      if (t === "Early hours") return 0;
      var m = /^(\d+)\s*h$/.exec(t);
      if (m) return { "2": 1, "4": 2, "6": 3, "12": 4, "24": 5 }[m[1]] || (6 + Number(m[1]));
      var dm = /^Day\s*(\d+)$/.exec(t);
      if (dm) return 10 + Number(dm[1]);
      return 100;
    };
    var pathogens = uniq(d.map(function (r) { return r.pathogen; }));
    var organisms = uniq(d.map(function (r) { return r.organism; }));
    var cols = pathogens.length > 4 ? 3 : 2;
    var rows = Math.ceil(pathogens.length / cols);
    var cellH = 190, cellW = 100 / cols;
    el.style.height = (rows * cellH + 70) + "px";

    var titles = [], grids = [], xAxes = [], yAxes = [], series = [];
    var colorOf = {};
    organisms.forEach(function (o, i) { colorOf[o] = PALETTE[i % PALETTE.length]; });

    pathogens.forEach(function (p, idx) {
      var r = Math.floor(idx / cols), c = idx % cols;
      var tps = uniq(d.filter(function (x) { return x.pathogen === p; })
        .map(function (x) { return x.timepoint; }))
        .sort(function (a, b) { return orderKey(a) - orderKey(b); });
      titles.push({ text: p, left: (c * cellW + cellW / 2) + "%", textAlign: "center",
        top: r * cellH + 26,
        textStyle: { color: C.ink, fontSize: 12, fontWeight: 700 } });
      grids.push({ left: (c * cellW + 7) + "%", width: (cellW - 12) + "%",
        top: r * cellH + 46, height: cellH - 86, containLabel: false });
      xAxes.push({ gridIndex: idx, type: "category", data: tps,
        axisLabel: { color: C.soft, fontSize: 9, interval: 0, rotate: tps.length > 4 ? 28 : 0 },
        axisLine: { lineStyle: { color: C.grid } }, axisTick: { show: false } });
      yAxes.push({ gridIndex: idx, type: "value",
        axisLabel: { color: C.soft, fontSize: 9 },
        splitLine: { lineStyle: { color: C.grid } },
        name: (c === 0 ? "DEGs" : ""), nameTextStyle: { color: C.soft, fontSize: 9 } });
      organisms.forEach(function (o) {
        series.push({
          name: o, type: "bar", xAxisIndex: idx, yAxisIndex: idx, barMaxWidth: 14,
          itemStyle: { color: colorOf[o], borderRadius: [3, 3, 0, 0] },
          data: tps.map(function (t) {
            var row = d.filter(function (x) {
              return x.pathogen === p && x.timepoint === t && x.organism === o;
            })[0];
            return row ? row.n_sig : null;
          })
        });
      });
    });

    render(el, Object.assign(base(), {
      title: titles,
      legend: { top: 2, textStyle: { color: C.muted }, data: organisms, itemGap: 14 },
      tooltip: Object.assign({}, base().tooltip, { trigger: "axis", axisPointer: { type: "shadow" } }),
      grid: grids, xAxis: xAxes, yAxis: yAxes, series: series
    }));
  };

  R.dgeScatter = function (el, d) {
    var organisms = uniq(d.map(function (r) { return r.organism; }));
    render(el, Object.assign(base(), {
      title: title("Noise and effect size", "median standard error vs median |log2FC|"),
      xAxis: Object.assign(axis("median SE"), { type: "value", scale: true }),
      yAxis: Object.assign(axis("median |log2FC|"), { type: "value", scale: true }),
      series: organisms.map(function (o, i) {
        return {
          name: o, type: "scatter", symbolSize: 9,
          itemStyle: { color: PALETTE[i % PALETTE.length], opacity: .8 },
          data: d.filter(function (r) { return r.organism === o && finite(r.median_se) && finite(r.median_abs_l2fc); })
            .map(function (r) { return { value: [r.median_se, r.median_abs_l2fc], name: r.pathogen + " · " + r.timepoint, n: r.n_sig }; })
        };
      })
    }));
  };

  R.btmScatter = function (el, d) {
    var rows = d.filter(function (r) { return finite(r.nes_mouse) && finite(r.nes_human); });
    var treatments = uniq(rows.map(function (r) { return r.treatment; }));
    var groups = uniq(rows.map(function (r) { return r.group; })).filter(Boolean);
    var state = { t: treatments.indexOf("Infection") >= 0 ? "Infection" : treatments[0] };
    el.innerHTML = '<div class="x-controls">' + treatments.map(function (t) {
      return '<button class="x-chip' + (t === state.t ? " active" : "") + '" data-t="' + t + '">' + t + "</button>";
    }).join("") + '</div><div class="x-canvas tall"></div>';
    var canvas = el.querySelector(".x-canvas");
    function draw() {
      var sub = rows.filter(function (r) { return r.treatment === state.t; });
      var opt = Object.assign(base(), {
        title: title("Cross-species module correlation", "BTM enrichment (NES): mouse vs human · " + state.t),
        xAxis: Object.assign(axis("NES mouse"), { type: "value", scale: true }),
        yAxis: Object.assign(axis("NES human"), { type: "value", scale: true }),
        series: groups.map(function (g, i) {
          return {
            name: g, type: "scatter", symbolSize: 7,
            itemStyle: { color: PALETTE[i % PALETTE.length], opacity: .75 },
            data: sub.filter(function (r) { return r.group === g; })
              .map(function (r) { return { value: [r.nes_mouse, r.nes_human], name: r.process, extra: r.pathogen + " · " + r.timepoint_comparison, status: r.status }; })
          };
        }).concat([{
          name: "y = x", type: "line", symbol: "none", silent: true,
          lineStyle: { color: "rgba(255,255,255,.35)", type: "dashed" }, data: [[-4, -4], [4, 4]]
        }])
      });
      opt.tooltip.formatter = function (p) {
        if (p.seriesName === "y = x") return "";
        return "<b>" + (p.data.name || "") + "</b><br>" + (p.data.extra || "") +
          "<br>NES mouse " + nfmt(p.value[0]) + " · human " + nfmt(p.value[1]) +
          (p.data.status ? "<br>status: " + p.data.status : "");
      };
      refit(canvas._chart, function () { canvas._chart.setOption(opt, true); });
    }
    render(canvas, {});
    draw();
    el.addEventListener("click", function (e) {
      var b = e.target.closest("[data-t]"); if (!b) return;
      state.t = b.getAttribute("data-t");
      el.querySelectorAll(".x-chip").forEach(function (c) { c.classList.toggle("active", c.getAttribute("data-t") === state.t); });
      draw();
    });
  };

  R.btmShared = function (el, d) {
    var map = {};
    d.forEach(function (r) {
      if (!r.process) return;
      if (!(r.process in map)) map[r.process] = { sum: 0, n: 0 };
      if (finite(r.percent)) { map[r.process].sum += r.percent; map[r.process].n++; }
    });
    var arr = Object.keys(map).map(function (k) { return { process: k, pct: map[k].n ? map[k].sum / map[k].n : null }; })
      .filter(function (r) { return finite(r.pct); })
      .sort(function (a, b) { return b.pct - a.pct; }).slice(0, 22).reverse();
    el.style.height = Math.max(340, arr.length * 24) + "px";
    render(el, Object.assign(base(), {
      title: title("Shared leading-edge genes", "% shared per blood transcriptional module"),
      grid: { left: 12, right: 40, top: 34, bottom: 40, containLabel: true },
      xAxis: Object.assign(axis("% shared"), { type: "value", max: 100 }),
      yAxis: Object.assign(axis(""), { type: "category", data: arr.map(function (r) { return r.process; }), axisLabel: { color: C.soft, fontSize: 10 } }),
      series: [{
        type: "bar", barWidth: "62%",
        itemStyle: { color: function (p) { return p.value >= 70 ? C.cyan : (p.value >= 45 ? C.peri : C.blue); }, borderRadius: [0, 4, 4, 0] },
        label: { show: true, position: "right", color: C.muted, fontSize: 9, formatter: "{c}%" },
        data: arr.map(function (r) { return Math.round(r.pct); })
      }]
    }));
  };

  R.evoScatter = function (el, d) {
    var bins = (el._bins || []).filter(function (b) { return b.var === el.dataset.var; })
      .sort(function (a, b) { return a.x - b.x; });
    var xv = el.dataset.var;
    var points = d.filter(function (r) { return finite(r[xv]) && finite(r.abs_log2fc_diff); });
    var fit = slope(points.map(function (r) { return r[xv]; }), points.map(function (r) { return r.abs_log2fc_diff; }));
    var name = xv === "dist_k80" ? "Kimura K80 distance" : "protein sequence identity (%)";
    var series = [
      { name: "genes", type: "scatter", symbolSize: 5,
        itemStyle: { color: C.peri, opacity: .45 },
        data: points.map(function (r) { return { value: [r[xv], r.abs_log2fc_diff], name: r.gene }; }) },
      { name: "binned mean", type: "line", smooth: true, symbolSize: 7, lineStyle: { color: C.cyan, width: 3 }, itemStyle: { color: C.cyan }, data: bins.map(function (b) { return [b.x, b.y]; }) }
    ];
    if (fit) series.push({ name: "trend", type: "line", symbol: "none", silent: true, lineStyle: { color: mode === "dark" ? "rgba(200,210,235,.5)" : "rgba(60,70,100,.45)", type: "dashed" }, data: [[Math.min.apply(null, points.map(function (r) { return r[xv]; })), 0], [Math.max.apply(null, points.map(function (r) { return r[xv]; })), 0]].map(function (p) { return [p[0], fit.m * p[0] + fit.b]; }) });
    var opt = Object.assign(base(), {
      title: title(name + " vs expression divergence", "each point = a gene · hover to see its symbol"),
      xAxis: Object.assign(axis(name), { type: "value", scale: true }),
      yAxis: Object.assign(axis("|Δlog2FC|"), { type: "value", scale: true, max: 4 }),
      series: series
    });
    opt.tooltip.formatter = function (p) {
      if (p.seriesName === "trend") return "";
      if (p.seriesName === "binned mean") return "binned mean<br>" + name + ": " + nfmt(p.value[0]) + "<br>|Δlog2FC|: " + nfmt(p.value[1]);
      return "<b>" + (p.data && p.data.name ? p.data.name : "") + "</b><br>" + name + ": " + nfmt(p.value[0]) + "<br>|Δlog2FC|: " + nfmt(p.value[1]);
    };
    render(el, opt);
  };

  R.regBars = function (el, d) {
    var arr = d.slice().sort(function (a, b) { return a.y - b.y; });
    el.style.height = Math.max(260, arr.length * 34) + "px";
    render(el, Object.assign(base(), {
      title: title("Expression divergence by regulatory class", "mean |Δlog2FC|"),
      grid: { left: 12, right: 48, top: 34, bottom: 40, containLabel: true },
      xAxis: Object.assign(axis("mean |Δlog2FC|"), { type: "value" }),
      yAxis: Object.assign(axis(""), { type: "category", data: arr.map(function (r) { return r.var + " — " + r.bin; }), axisLabel: { color: C.soft, fontSize: 10 } }),
      series: [{
        type: "bar", barWidth: "55%",
        itemStyle: { color: function (p) { return p.value > 1.1 ? C.blue : C.cyan; }, borderRadius: [0, 4, 4, 0] },
        label: { show: true, position: "right", color: C.muted, fontSize: 10, formatter: function (p) { return nfmt(p.value, 2); } },
        data: arr.map(function (r) { return r.y; }),
        tooltip: { formatter: function (p) { return arr[p.dataIndex].var + " — " + arr[p.dataIndex].bin + "<br>mean |Δlog2FC| " + nfmt(arr[p.dataIndex].y) + "<br>n = " + arr[p.dataIndex].n; } }
      }]
    }));
  };

  R.perfFacets = function (el, d) {
    var tasks = uniq(d.map(function (r) { return r.task; }));
    var cellH = 210;
    el.style.height = (tasks.length * cellH + 30) + "px";

    var titles = [], legends = [], grids = [], xAxes = [], yAxes = [], series = [];
    tasks.forEach(function (task, idx) {
      var sub = d.filter(function (r) { return r.task === task; });
      var models = uniq(sub.map(function (r) { return r.model; }));
      var sets = uniq(sub.map(function (r) { return r.feature_set; }));
      var metric = sub.length ? sub[0].metric : "value";
      var yName = metric === "rsq" ? "R²" : "ROC-AUC";

      titles.push({
        text: task + "  ·  " + yName, left: "0%", width: "100%", textAlign: "center",
        top: idx * cellH + 6,
        textStyle: { color: C.ink, fontSize: 12, fontWeight: 700 }
      });
      legends.push({
        data: sets, right: "1%", top: idx * cellH + 4,
        textStyle: { color: C.muted, fontSize: 10 }, itemGap: 10, itemWidth: 12, itemHeight: 8
      });
      grids.push({
        left: "9%", width: "88%", top: idx * cellH + 40, height: cellH - 92,
        containLabel: false
      });
      xAxes.push({
        gridIndex: idx, type: "category", data: models,
        axisLabel: { color: C.soft, fontSize: 10, interval: 0, rotate: 0, margin: 6 },
        axisLine: { lineStyle: { color: C.grid } }, axisTick: { show: false }
      });
      var y = {
        gridIndex: idx, type: "value",
        axisLabel: { color: C.soft, fontSize: 9 },
        splitLine: { lineStyle: { color: C.grid } }
      };
      if (metric !== "rsq") y.max = 1;
      yAxes.push(y);
      sets.forEach(function (s, i) {
        series.push({
          name: s, type: "bar", xAxisIndex: idx, yAxisIndex: idx, barMaxWidth: 38,
          itemStyle: { color: PALETTE[i % PALETTE.length], borderRadius: [4, 4, 0, 0] },
          data: models.map(function (m) {
            var row = sub.filter(function (r) { return r.model === m && r.feature_set === s; })[0];
            return row ? Number(row.value) : null;
          })
        });
      });
    });

    render(el, Object.assign(base(), {
      title: titles,
      legend: legends,
      tooltip: Object.assign({}, base().tooltip, { trigger: "axis", axisPointer: { type: "shadow" } }),
      grid: grids, xAxis: xAxes, yAxis: yAxes, series: series
    }));
  };

  R.geneFacets = function (el, d) {
    var all = d.filter(function (r) { return finite(r.rank_human) && finite(r.pred_rank); });
    var pathogens = uniq(all.map(function (r) { return r.pathogen; }));
    var cols = 2, cellH = 268, cellW = 100 / cols;
    var nRows = Math.ceil(pathogens.length / cols);
    function isConc(r) { return r.sign_concordant === true || r.sign_concordant === "TRUE"; }

    el.innerHTML =
      '<div class="x-controls"><input class="x-search" type="search" ' +
      'placeholder="Search a gene (e.g. MMP8)…" aria-label="Search a gene">' +
      '<span class="x-table-note"></span></div><div class="x-canvas"></div>';
    var canvas = el.querySelector(".x-canvas"), note = el.querySelector(".x-table-note");
    canvas.style.height = (nRows * cellH + 30) + "px";
    var state = { q: "" };

    function build() {
      var titles = [], grids = [], xAxes = [], yAxes = [], series = [];
      pathogens.forEach(function (p, idx) {
        var r = Math.floor(idx / cols), c = idx % cols;
        var sub = all.filter(function (x) { return x.pathogen === p; });
        var ok = sub.filter(isConc), bad = sub.filter(function (x) { return !isConc(x); });
        titles.push({
          text: p + "  (" + sub.length + " genes)", left: (c * cellW) + "%", width: (cellW - 4) + "%",
          textAlign: "center", top: r * cellH + 24,
          textStyle: { color: C.ink, fontSize: 12, fontWeight: 700 }
        });
        grids.push({
          left: (c * cellW + (c === 0 ? 12 : 7)) + "%", width: (cellW - (c === 0 ? 15 : 11)) + "%",
          top: r * cellH + 48, height: cellH - 104, containLabel: false
        });
        xAxes.push({ gridIndex: idx, type: "value", min: 0, max: 100,
          name: (r === nRows - 1 ? "observed rank (human)" : ""),
          nameLocation: "middle", nameGap: 24, nameTextStyle: { color: C.soft, fontSize: 9 },
          axisLabel: { color: C.soft, fontSize: 9 }, splitLine: { lineStyle: { color: C.grid } } });
        yAxes.push({ gridIndex: idx, type: "value", min: 0, max: 100,
          name: (c === 0 ? "predicted rank" : ""),
          nameLocation: "middle", nameGap: 30, nameTextStyle: { color: C.soft, fontSize: 9 },
          axisLabel: { color: C.soft, fontSize: 9 }, splitLine: { lineStyle: { color: C.grid } } });
        series.push({ name: "concordant", type: "scatter", xAxisIndex: idx, yAxisIndex: idx, symbolSize: 4, itemStyle: { color: C.cyan, opacity: .4 },
          data: ok.map(function (x) { return { value: [x.rank_human, x.pred_rank], name: x.hgnc_symbol }; }) });
        series.push({ name: "discordant", type: "scatter", xAxisIndex: idx, yAxisIndex: idx, symbolSize: 4, itemStyle: { color: C.pink, opacity: .4 },
          data: bad.map(function (x) { return { value: [x.rank_human, x.pred_rank], name: x.hgnc_symbol }; }) });
      });

      var q = state.q.trim().toUpperCase();
      var matches = q ? all.filter(function (x) { return String(x.hgnc_symbol).toUpperCase().indexOf(q) === 0; }) : [];
      var legendData = ["concordant", "discordant"];
      if (matches.length) {
        legendData.unshift("match");
        pathogens.forEach(function (p, idx) {
          var hit = matches.filter(function (m) { return m.pathogen === p; });
          if (!hit.length) return;
          series.push({ name: "match", type: "effectScatter", xAxisIndex: idx, yAxisIndex: idx, symbolSize: 15,
            itemStyle: { color: C.lime },
            data: hit.map(function (x) { return { value: [x.rank_human, x.pred_rank], name: x.hgnc_symbol }; }) });
        });
      }

      var opt = Object.assign(base(), {
        title: titles,
        legend: { top: 2, textStyle: { color: C.muted }, data: legendData, itemGap: 14 },
        tooltip: Object.assign({}, base().tooltip, { trigger: "item" }),
        grid: grids, xAxis: xAxes, yAxis: yAxes, series: series
      });
      opt.tooltip.formatter = function (p) {
        return "<b>" + (p.data && p.data.name ? p.data.name : "") + "</b><br>observed " + nfmt(p.value[0], 1) +
          " · predicted " + nfmt(p.value[1], 1) + "<br>" + p.seriesName;
      };
      return opt;
    }

    function draw() {
      var opt = build();
      if (canvas._chart && !canvas._chart.isDisposed()) {
        canvas._chart.setOption(opt, true);
        canvas._chart.resize();
      } else {
        render(canvas, opt);
      }
      var q = state.q.trim().toUpperCase();
      var matches = q ? all.filter(function (x) { return String(x.hgnc_symbol).toUpperCase().indexOf(q) === 0; }) : [];
      if (!q) note.textContent = "Search a gene to highlight it across every condition.";
      else if (!matches.length) note.textContent = "No gene starts with \u201c" + state.q.trim() + "\u201d.";
      else {
        var shown = matches.slice(0, 4).map(function (m) {
          return m.hgnc_symbol + " (" + m.pathogen + " · obs " + nfmt(m.rank_human, 0) + " / pred " + nfmt(m.pred_rank, 0) + ")";
        });
        note.textContent = matches.length + " match" + (matches.length > 1 ? "es" : "") + ": " +
          shown.join("; ") + (matches.length > 4 ? " …" : "");
      }
    }

    draw();
    var timer = null;
    el.querySelector(".x-search").addEventListener("input", function (e) {
      state.q = e.target.value;
      clearTimeout(timer);
      timer = setTimeout(draw, 200);
    });
  };

  R.priorityTable = function (el, d) {
    var cols = [
      ["hgnc_symbol", "Gene"], ["process", "Process"], ["rank_mouse", "Rank mouse"],
      ["rank_human", "Rank human"], ["score_shared", "Shared"], ["score_rank", "Rank"],
      ["score_direction", "Direction"], ["score_translational", "Translational"], ["status_original", "Status"]
    ];
    el.innerHTML = '<div class="x-table-wrap"><table class="x-table"><thead><tr>' +
      cols.map(function (c) { return '<th data-k="' + c[0] + '">' + c[1] + "</th>"; }).join("") +
      "</tr></thead><tbody></tbody></table></div>";
    var tbody = el.querySelector("tbody"), sort = { k: "score_translational", dir: -1 };
    function draw() {
      var rows = d.slice().sort(function (a, b) { return (Number(a[sort.k]) - Number(b[sort.k])) * sort.dir; });
      tbody.innerHTML = rows.map(function (r) {
        return "<tr>" + cols.map(function (c) {
          var v = r[c[0]];
          if (/^score_/.test(c[0]) || /^rank_/.test(c[0])) v = nfmt(v, 1);
          return "<td>" + (v == null ? "–" : v) + "</td>";
        }).join("") + "</tr>";
      }).join("");
    }
    el.querySelector("thead").addEventListener("click", function (e) {
      var k = e.target.getAttribute("data-k"); if (!k) return;
      if (sort.k === k) sort.dir *= -1; else { sort.k = k; sort.dir = -1; }
      draw();
    });
    draw();
  };

  R.importanceBars = function (el, d) {
    var tasks = uniq(d.map(function (r) { return r.task; }));
    var state = { task: tasks[0] };
    el.innerHTML = '<div class="x-controls">' + tasks.map(function (t) {
      return '<button class="x-chip' + (t === state.task ? " active" : "") + '" data-task="' + t + '">' + t + "</button>";
    }).join("") + '</div><div class="x-canvas"></div>';
    var canvas = el.querySelector(".x-canvas");
    function draw() {
      var sub = d.filter(function (r) { return r.task === state.task; });
      var sets = uniq(sub.map(function (r) { return r.feature_set; }));
      // use the richest feature set available for this task
      var useSet = sets[sets.length - 1];
      var rows = sub.filter(function (r) { return r.feature_set === useSet; })
        .sort(function (a, b) { return a.importance - b.importance; }).slice(-15);
      el.style.height = "auto";
      canvas.style.height = Math.max(320, rows.length * 26) + "px";
      var opt = Object.assign(base(), {
        title: title("Feature importance", state.task + " · " + useSet),
        grid: { left: 12, right: 48, top: 34, bottom: 40, containLabel: true },
        xAxis: Object.assign(axis("importance"), { type: "value" }),
        yAxis: Object.assign(axis(""), { type: "category", data: rows.map(function (r) { return r.feature_name_original; }), axisLabel: { color: C.soft, fontSize: 10 } }),
        series: [{ type: "bar", barWidth: "60%", itemStyle: { color: C.cyan, borderRadius: [0, 4, 4, 0] }, data: rows.map(function (r) { return r.importance; }) }]
      });
      refit(canvas._chart, function () { canvas._chart.setOption(opt, true); });
    }
    render(canvas, {});
    draw();
    el.addEventListener("click", function (e) {
      var b = e.target.closest("[data-task]"); if (!b) return;
      state.task = b.getAttribute("data-task");
      el.querySelectorAll(".x-chip").forEach(function (c) { c.classList.toggle("active", c.getAttribute("data-task") === state.task); });
      draw();
    });
  };

  /* ── lazy loading of data + reveal ──────────────────────────────────────── */
  function load(el) {
    if (el._loaded) return;
    el._loaded = true;
    var name = el.dataset.chart;
    var dataFile = el.dataset.data;
    var binsFile = el.dataset.bins;
    var jobs = [fetch(dataFile).then(function (r) { return r.json(); })];
    if (binsFile) jobs.push(fetch(binsFile).then(function (r) { return r.json(); }));
    Promise.all(jobs).then(function (res) {
      if (res[1]) el._bins = res[1];
      el._data = res[0];
      if (R[name]) R[name](el, res[0]);
    }).catch(function (err) {
      el.innerHTML = '<p class="x-table-note">Data unavailable (' + name + ').</p>';
      if (window.console) console.warn(name, err);
    });
  }

  /* ── theme (light default, optional dark) ───────────────────────────────── */
  function rerenderAll() {
    instances.forEach(function (i) { try { if (!i.isDisposed()) i.dispose(); } catch (e) { /* ignore */ } });
    instances.length = 0;
    document.querySelectorAll("[data-chart]").forEach(function (el) {
      if (!(el._loaded && el._data && R[el.dataset.chart])) return;
      try { el._chart = null; R[el.dataset.chart](el, el._data); }
      catch (e) { if (window.console) console.warn("theme rerender failed:", el.dataset.chart, e); }
    });
  }
  var savedMode = "light";
  try { savedMode = localStorage.getItem("m2h-explore-theme") || "light"; } catch (e) { /* ignore */ }
  applyMode(savedMode, false);
  var themeBtn = document.getElementById("xThemeToggle");
  if (themeBtn) {
    themeBtn.addEventListener("click", function () {
      applyMode(mode === "dark" ? "light" : "dark", true);
      // reload so every chart is rebuilt with the new palette (robust + no flashes)
      window.location.reload();
    });
  }

  var revealIO = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) {
      if (!e.isIntersecting) return;
      e.target.classList.add("in");
      var node = e.target.querySelector("[data-chart]") || (e.target.matches("[data-chart]") ? e.target : null);
      if (node) load(node);
      revealIO.unobserve(e.target);
    });
  }, { rootMargin: "0px 0px -12% 0px", threshold: 0.01 });

  document.querySelectorAll(".x-card, [data-chart]").forEach(function (el) { revealIO.observe(el); });

  /* scrollytelling: activate the step nearest the viewport middle */
  var steps = Array.prototype.slice.call(document.querySelectorAll(".x-step"));
  if (steps.length) {
    var spy = function () {
      var mid = window.innerHeight * 0.5, best = null, bestD = 1e9;
      steps.forEach(function (s) {
        var r = s.getBoundingClientRect(), d = Math.abs((r.top + r.bottom) / 2 - mid);
        if (d < bestD) { bestD = d; best = s; }
      });
      steps.forEach(function (s) { s.classList.toggle("active", s === best); });
      var stage = document.querySelector(".x-stage [data-chart]");
      if (best && stage && best.dataset.focus && stage.dataset.focus !== best.dataset.focus) {
        stage.dataset.focus = best.dataset.focus;
        stage.dispatchEvent(new CustomEvent("stagefocus", { detail: best.dataset.focus }));
      }
    };
    window.addEventListener("scroll", spy, { passive: true });
    spy();
  }
})();
